import {clone,defaults,bridgeQuote,bridgeClaim,vestFraction,poolEconomics,div,sum,monthlyBudget,rewardCumulative} from './model.js';
import {makeMarket,executeBuy,executeSell,guardedSell,guardedBuy} from './market.js';
import {newVault,curveTrade,curveQuote,positionRedemptionQuote,sharesForWithdrawalOutput,curveAudit} from './curve.js';
const DAYS=365.25/12,EPS=1e-8;
const positive=(x,label='Amount')=>{const n=Number(x);if(!Number.isFinite(n)||n<=0)throw Error(label+' must be positive and finite.');return n;};
const log=(s,type,detail)=>{s.log.unshift({day:s.day,type,detail});s.log=s.log.slice(0,150);};
export function newMock(c=defaults()){return {wallet:clone(c.mock.wallet),market:makeMarket(c),vaults:Object.fromEntries(c.projects.map(p=>[p.id,newVault(p)])),bridgeClaimed:0,releasedRestricted:0,owners:{},usedNonces:[],burnedLegacy:0,day:0,log:[],rewardSpent:0,realGenerated:0,realPaid:0,externalTransfers:0,verifiedMilestones:{},restrictedPolicy:'Collateral-only principal and rewards; never transferable.'};}
const findPosition=(s,id,restricted)=>s.wallet.positions.find(p=>p.projectId===id&&p.restricted===restricted);
function getPosition(s,id,restricted){let p=findPosition(s,id,restricted);if(!p){p={projectId:id,restricted,shares:0,principalBasis:0,realUSD:0,rewardLiquid:0,rewardRestricted:0,debtUSD:0,transferable:!restricted};s.wallet.positions.push(p);}return p;}
function claimableValue(s,pos){return positionRedemptionQuote(s.vaults[pos.projectId],pos.shares).output;}
function debtLimit(s,c,pos){return claimableValue(s,pos)*s.market.mid*(1-c.stress.collateralHaircut)*c.stress.borrowLTV;}
export function mockAction(state,c,type,args={}){const s=clone(state),w=s.wallet,amount=Number(args.amount),p=c.projects.find(x=>x.id===args.projectId),restricted=!!args.restricted,owner=args.owner||'demo-owner';let q;
if(type==='reset')return newMock(c);
if(type==='buy'){const a=positive(amount);if(a>w.usd+EPS)throw Error('Insufficient USD.');q=guardedBuy(s.market,a,c.stress.maxExecutionSlippage,true);w.usd-=q.spent;w.liquid+=q.tokens;log(s,type,`Bought ${q.tokens.toFixed(2)} CCLX for $${a.toFixed(2)}.`);}
else if(type==='sell'){const a=positive(amount);if(a>w.liquid+EPS)throw Error('Only unrestricted liquid CCLX can be sold.');q=guardedSell(s.market,a,c.stress.maxExecutionSlippage,true);w.liquid-=q.filled;w.usd+=q.quote;log(s,type,`Sold ${a.toFixed(2)} CCLX for $${q.quote.toFixed(2)}.`);}
else if(type==='convert'){const a=positive(amount);if(s.day>c.bridge.claimWindow)throw Error('The mock claim window is closed.');if(a>w.legacy+EPS)throw Error('Insufficient legacy entitlement.');const nonce=String(args.nonce||`demo-claim-${s.usedNonces.length+1}`);if(s.usedNonces.includes(nonce))throw Error('Claim nonce has already been consumed.');const cfg=clone(c);cfg.bridge.claimed+=s.bridgeClaimed;cfg.bridge.registered-=s.burnedLegacy;const claim=bridgeClaim(cfg,a,s.owners[owner]||0);w.legacy-=a;w.unvestedRestricted+=claim.restrictedIssued;s.bridgeClaimed+=claim.restrictedIssued;s.burnedLegacy+=a;s.owners[owner]=(s.owners[owner]||0)+claim.restrictedIssued;s.usedNonces.push(nonce);log(s,type,`Mock burn: ${a.toFixed(0)} CO2BIT → ${claim.restrictedIssued.toFixed(2)} non-transferable CCLX. Allocation vesting applies.`);}
else if(type==='allocate'){const a=positive(amount);if(!p)throw Error('Choose a project.');const source=restricted?(args.source==='reward'?'restrictedRewards':'restricted'):'liquid';if(a>w[source]+EPS)throw Error('Insufficient eligible '+source+' balance.');const quote=curveTrade(s.vaults[p.id],a,'deposit');w[source]-=a;const pos=getPosition(s,p.id,restricted);pos.shares+=quote.shares;pos.principalBasis+=a;log(s,type,`Deposited ${a.toFixed(2)} ${restricted?'restricted':'liquid'} CCLX into ${p.name}; ${quote.shares.toFixed(2)} receipt shares minted.`);}
else if(type==='withdraw'){const a=positive(amount);if(!p)throw Error('Choose a project.');const pos=findPosition(s,p.id,restricted);if(!pos||!pos.shares)throw Error('No eligible position.');const value=claimableValue(s,pos);if(a>value+EPS)throw Error('Withdrawal exceeds current executable redemption value.');const shares=sharesForWithdrawalOutput(s.vaults[p.id],a);if(shares>pos.shares+EPS)throw Error('Insufficient receipt shares.');const quote=curveQuote(s.vaults[p.id],shares,'withdraw');const remainValue=claimableValue(s,{...pos,shares:pos.shares-shares});if(!restricted&&pos.debtUSD>0&&pos.debtUSD>remainValue*s.market.mid*(1-c.stress.collateralHaircut)*c.stress.borrowLTV+EPS)throw Error('Withdrawal would breach the borrowing LTV.');curveTrade(s.vaults[p.id],shares,'withdraw');const fraction=div(shares,pos.shares);pos.principalBasis*=1-fraction;pos.shares-=shares;w[restricted?'restricted':'liquid']+=quote.output;log(s,type,`Withdrew ${quote.output.toFixed(2)} ${restricted?'restricted':'liquid'} CCLX by burning ${shares.toFixed(2)} receipts. Provenance preserved; curve fee applied.`);}
else if(type==='claim'){let real=0,free=0,locked=0;for(const pos of w.positions){real+=pos.realUSD;free+=pos.rewardLiquid;locked+=pos.rewardRestricted;pos.realUSD=0;pos.rewardLiquid=0;pos.rewardRestricted=0;}w.usd+=real;w.liquid+=free;w.restrictedRewards+=locked;s.realPaid+=real;log(s,type,`Claimed $${real.toFixed(2)} real yield, ${free.toFixed(2)} free reward CCLX and ${locked.toFixed(2)} collateral-only reward CCLX.`);}
else if(type==='advance'){const days=Math.min(365,Math.floor(positive(amount,'Days')));const start=s.day,end=start+days;const now=vestFraction(end/DAYS,c.bridge.cliff,c.bridge.linear);const eligible=Math.min(w.unvestedRestricted,Math.max(0,s.bridgeClaimed*now-s.releasedRestricted));w.unvestedRestricted-=eligible;w.restricted+=eligible;s.releasedRestricted+=eligible;for(let day=start;day<end;day++){const month=Math.floor(day/DAYS),locked=Object.fromEntries(c.projects.map(p=>[p.id,s.vaults[p.id].backing])),pools=poolEconomics(c,month,s.market.mid,locked);s.realGenerated+=sum(pools.map(p=>p.distributable))/DAYS;const dailyCeiling=rewardCumulative((day+1)/DAYS,c.rewardBudget)-rewardCumulative(day/DAYS,c.rewardBudget);const rewardScale=div(dailyCeiling,monthlyBudget(c,month));s.rewardSpent+=sum(pools.map(p=>p.bootstrap))*rewardScale;for(const pos of w.positions){const pool=pools.find(p=>p.id===pos.projectId),vault=s.vaults[pos.projectId];if(!pool||!vault.shares)continue;const share=pos.shares/vault.shares;pos.realUSD+=pool.distributable*share/DAYS;const reward=pool.bootstrap*share*rewardScale;if(pos.restricted)pos.rewardRestricted+=reward;else pos.rewardLiquid+=reward;}}s.day=end;log(s,type,`Advanced ${days} days. ${eligible.toFixed(2)} restricted CCLX became eligible for project allocation.`);}
else if(type==='transfer'){const a=positive(amount);if(restricted||args.source==='restrictedRewards'||args.source==='receipt')throw Error('Restricted principal, rewards and receipts cannot be transferred.');if(a>w.liquid+EPS)throw Error('Insufficient liquid CCLX.');w.liquid-=a;s.externalTransfers+=a;log(s,type,`Transferred ${a.toFixed(2)} unrestricted CCLX to a fictitious external wallet.`);}
else if(type==='wrap'||type==='receiptTransfer'||type==='pledge'){if(restricted)throw Error('Restricted balances and receipts cannot be wrapped, transferred, pledged or borrowed against.');throw Error('This mock does not implement transferable receipt wrappers.');}
else if(type==='borrow'){const a=positive(amount);if(!c.stress.borrowEnabled)throw Error('Borrowing is disabled in the proposed baseline.');if(restricted)throw Error('Borrowing against restricted collateral is prohibited.');if(!p)throw Error('Choose a project.');const pos=findPosition(s,p.id,false);if(!pos||pos.debtUSD+a>debtLimit(s,c,pos)+EPS)throw Error('Insufficient eligible collateral / LTV exceeded.');pos.debtUSD+=a;w.usd+=a;log(s,type,`Mock debt +$${a.toFixed(2)} against unrestricted collateral.`);}
else if(type==='repay'){const a=positive(amount),pos=findPosition(s,args.projectId,false);if(!pos||a>pos.debtUSD+EPS||a>w.usd+EPS)throw Error('Invalid repayment.');pos.debtUSD-=a;w.usd-=a;log(s,type,`Repaid $${a.toFixed(2)} mock debt.`);}
else if(type==='verify'){if(!p)throw Error('Choose a project.');const current=s.verifiedMilestones[p.id]??p.stage;if(current>=p.milestones.length)throw Error('All mock milestones are already verified.');s.verifiedMilestones[p.id]=current+1;log(s,type,`Mock milestone ${current+1} verified for ${p.name}. No automatic token price increase or reserve mint.`);}
else throw Error('Unknown action: '+type);
return s;}
export function mockMetrics(s,c){const locked=Object.fromEntries(c.projects.map(p=>[p.id,s.vaults[p.id].backing]));const pools=poolEconomics(c,Math.floor(s.day/DAYS),s.market.mid,locked);return {pools,locked:sum(s.wallet.positions.map(p=>claimableValue(s,p))),pendingReal:sum(s.wallet.positions.map(p=>p.realUSD)),pendingRewards:sum(s.wallet.positions.map(p=>p.rewardLiquid+p.rewardRestricted)),bridge:bridgeQuote(c),positions:s.wallet.positions.map(p=>{const quote=positionRedemptionQuote(s.vaults[p.projectId],p.shares);return {...p,value:quote.output,proportionalValue:quote.proportionalValue,marginalValue:quote.marginalValue,exitFee:quote.fee,debtLimit:p.restricted?0:debtLimit(s,c,p)};}),vaults:Object.values(s.vaults).map(curveAudit)};}
